# owner: platform

import unittest
from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

def _gaps_for(worked_texts, opening_text):
    worked = [parse_span(text) for text in worked_texts]
    return find_gaps(worked, parse_span(opening_text))

class GapTests(unittest.TestCase):
    # ---
    def test_nobody_working_is_one_gap(self):
        self.assertEqual(
            _gaps_for([], "09:00-17:00"),
            ["gap 09:00-17:00 (480 min)"]
        )

    # ---
    def test_fully_covered_has_no_gaps(self):
        self.assertEqual(_gaps_for(["09:00-17:00"], "09:00-17:00"), [])

    # ---
    def test_gap_between_shifts(self):
        self.assertEqual(
            _gaps_for(["09:00-12:00", "13:00-17:00"], "09:00-17:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    # ---
    def test_gaps_at_both_ends(self):
        self.assertEqual(
            _gaps_for(["09:30-16:00"], "09:00-17:00"),
            ["gap 09:00-09:30 (30 min)", "gap 16:00-17:00 (60 min)"]
        )

    # ---
    def test_overlapping_and_touching_spans_leave_no_false_gap(self):
        self.assertEqual(
            _gaps_for(["09:00-12:00", "11:00-13:00", "13:00-14:00"], "09:00-17:00"),
            ["gap 14:00-17:00 (180 min)"]
        )

    # ---
    def test_order_of_spans_does_not_matter(self):
        self.assertEqual(
            _gaps_for(["13:00-17:00", "09:00-12:00"], "09:00-17:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    # ---
    def test_several_gaps_come_back_in_time_order(self):
        self.assertEqual(
            _gaps_for(["10:00-11:00", "12:00-13:00", "15:00-16:00"], "09:00-17:00"),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
                "gap 13:00-15:00 (120 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    # ---
    def test_span_starting_before_opening_raises(self):
        with self.assertRaises(ValueError):
            _gaps_for(["08:00-10:00"], "09:00-17:00")

    # ---
    def test_span_ending_after_closing_raises(self):
        with self.assertRaises(ValueError):
            _gaps_for(["16:00-18:00"], "09:00-17:00")

    # ---
    def test_span_wider_than_opening_raises(self):
        with self.assertRaises(ValueError):
            _gaps_for(["08:00-18:00"], "09:00-17:00")

    # ---
    def test_error_names_the_span_outside_hours(self):
        with self.assertRaisesRegex(ValueError, "08:00-10:00"):
            _gaps_for(["08:00-10:00"], "09:00-17:00")
